-- Official Iranian calendar (holidays + occasions), Jalali years 1370-1430.
-- Sourced from the free/community 'PersianHoliday' dataset (mined from time.ir):
-- https://github.com/samanzamani/PersianHoliday -- global reference data, not
-- tied to any organization. Read-only from the app's perspective.
create table public.calendar_events (
  id uuid primary key default gen_random_uuid(),
  jalali_year int not null,
  jalali_month int not null check (jalali_month between 1 and 12),
  jalali_day int not null check (jalali_day between 1 and 31),
  gregorian_date date not null,
  title text not null,
  is_holiday boolean not null default false
);

create index calendar_events_gregorian_idx on public.calendar_events (gregorian_date);
create index calendar_events_jalali_idx on public.calendar_events (jalali_year, jalali_month, jalali_day);

alter table public.calendar_events enable row level security;

create policy "calendar_events_select_all" on public.calendar_events for select
  using (true);

grant select on public.calendar_events to authenticated;

